def transform(grid):
    # The long, connected stroke marks the replacement color. Other large,
    # filled objects are recolored to it.
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    # A marker is a color with a long contiguous straight run, typically
    # forming a line or L; choose the color with the greatest such run.
    runs = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            for dr, dc in ((0,1),(1,0)):
                n = 1
                while 0 <= r+dr*n < h and 0 <= c+dc*n < w and grid[r+dr*n][c+dc*n] == v:
                    n += 1
                runs[v] = max(runs.get(v, 0), n)
    marker = max(runs, key=runs.get)

    # Recolor the prominent non-marker object color.
    area = Counter()
    for color, cells in comps:
        if color != marker:
            area[color] += len(cells)
    target = max(area, key=area.get)
    return [[marker if v == target else v for v in row] for row in grid]
